import{z as i,x as n,o as E,c as d,q as B,j as l,D as e,d as o,s as A,S as t,b as s}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"SBOM 与可复现构建","description":"","frontmatter":{"title":"SBOM 与可复现构建","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sbom-reproducible-builds.md","filePath":"cs/sbom-reproducible-builds.md","lastUpdated":1791063341000}'),p={name:"cs/sbom-reproducible-builds.md"};function c(m,a,h,u,b,D){const r=n("Mermaid");return E(),d("div",null,[a[2]||(a[2]=B('<h1 id="sbom-与可复现构建" tabindex="-1">SBOM 与可复现构建 <a class="header-anchor" href="#sbom-与可复现构建" aria-label="Permalink to &quot;SBOM 与可复现构建&quot;">​</a></h1><div class="epigraph"><p>你跑的那份二进制，必须能回答「里面有哪些依赖、是不是宣称的那份源码编出来的」。SBOM 是清单；可复现构建让第三方复验哈希。</p><footer>—— NTIA/CISA 对 SBOM 的最小要素；Debian 可复现构建；Wheeler 对信任编译器的讨论</footer></div><p>上一课<a href="/cs/browser-sandbox">浏览器沙箱</a>缩小运行时权限。缺口是<strong>产物从哪来</strong>：依赖与编译器。本课收清单与复现，不把供应链攻击写成操作手册。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SolarWinds 一类事故说明签名过的更新仍可能背刺——点名机制：构建系统被插。SBOM：组件名与版本。可复现：同样源→同样哈希。缺口是工程合同，不是密码学新原语。</p><h3 id="时间戳与路径" tabindex="-1">时间戳与路径 <a class="header-anchor" href="#时间戳与路径" aria-label="Permalink to &quot;时间戳与路径&quot;">​</a></h3><p>不可复现常是嵌入时间、乱序、绝对路径。要规范化。</p><p><span class="marginnote">CISA SBOM。Reproducible Builds 项目。Ken Thompson 的信任信任攻击是极限：编译器自身。</span></p><p><span class="marginnote">「SBOM」就是软件物料清单——像食品包装上的配料表：列出二进制里每个组件的名字与版本。有了它，Log4Shell 一爆发你才能在几分钟内查出自家哪些产物受影响，否则只能全网翻依赖树。</span></p><p><span class="marginnote">数字实例：不可复现的经典来源是构建路径——同一次编译，路径 <code>/home/alice/project</code> 与 <code>/home/bob/project</code> 会把路径字符串嵌进调试信息，产物哈希就不同。规范化（固定路径、剔除时间戳、固定文件顺序）之后，两人才算出同一个哈希。</span></p><p><span class="marginnote">常见误区：初学者容易以为「签名 = 安全」。签名只证明「这份产物出自持钥者」，不证明「产物对应宣称的源码、没夹带别的」；可复现构建才把「源码 → 哈希」这条链交给第三方复验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：只锁版本号 vs 锁哈希 vs 复现。签名要在复现哈希上。下一课依赖混淆：名字空间抢注。</p>',14)),(E(),l(t,null,{default:e(()=>[A(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E4%B8%8E%E4%BE%9D%E8%B5%96%E5%93%88%E5%B8%8C%22%5D%20--%3E%20BUILD%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%E6%9E%84%E5%BB%BA%22%5D%0A%20%20BUILD%20--%3E%20BIN%5B%22%E4%BA%A7%E7%89%A9%E5%93%88%E5%B8%8C%22%5D%0A%20%20SBOM%5B%22SBOM%22%5D%20--%3E%20INV%5B%22%E6%B8%85%E5%8D%95%E5%8F%AF%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20BIN%20--%3E%20SIG%5B%22%E7%AD%BE%E5%90%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[o("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"完整性要从运行时收到构建时。下一课依赖混淆：包管理器如何把名字解析到错误发布者。",-1)),(E(),l(t,null,{default:e(()=>[A(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E5%AE%A3%E7%A7%B0%3A%20%E6%BA%90%E7%A0%81%20S%20%E7%BC%96%E5%87%BA%E4%BA%A7%E7%89%A9%20B%22%5D%20--%3E%20OTHER%5B%22%E7%AC%AC%E4%B8%89%E6%96%B9%E5%8F%96%E5%90%8C%E6%A0%B7%20S%20%E4%B8%8E%E5%B7%A5%E5%85%B7%E9%93%BE%22%5D%0A%20%20OTHER%20--%3E%20REB%5B%22%E7%8B%AC%E7%AB%8B%E6%9E%84%E5%BB%BA(%E8%A7%84%E8%8C%83%E5%8C%96%E7%8E%AF%E5%A2%83)%22%5D%0A%20%20REB%20--%3E%20H1%5B%22%E7%AE%97%E5%87%BA%E5%93%88%E5%B8%8C%20H'%22%5D%0A%20%20VENDOR%5B%22%E5%8E%82%E5%95%86%E4%BA%A7%E7%89%A9%20B%22%5D%20--%3E%20H2%5B%22%E7%AE%97%E5%87%BA%E5%93%88%E5%B8%8C%20H%22%5D%0A%20%20H1%20--%3E%20CMP%7B%22H'%20%3D%20H%20%3F%22%7D%0A%20%20CMP%20--%20%22%E7%9B%B8%E7%AD%89%22%20--%3E%20OK%5B%22%E5%8F%AF%E4%BF%A1%3A%20%E4%BA%A7%E7%89%A9%E7%A1%AE%E7%94%B1%E5%AE%A3%E7%A7%B0%E6%BA%90%E7%A0%81%E8%80%8C%E6%9D%A5%22%5D%0A%20%20CMP%20--%20%22%E4%B8%8D%E7%AD%89%22%20--%3E%20ALARM%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%3A%20%E6%9E%84%E5%BB%BA%E8%A2%AB%E6%8F%92%E6%88%96%E7%8E%AF%E5%A2%83%E4%B8%8D%E9%80%8F%E6%98%8E%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p>这张图回答的问题是：可复现构建如何把「口头宣称」变成「可独立验证」——第三方不需要信任构建农场，只要重跑一遍规范化构建并比对哈希，不等就当场报警。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写投毒构建农场的步骤。依赖混淆下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>沙箱不管你编进了谁的库。</li><li>SBOM 列组件；可复现复验哈希。</li><li>签名应钉复现产物。</li><li>下一课依赖混淆。</li><li>出处：CISA/NTIA SBOM；Reproducible Builds；Thompson, Reflections on Trusting Trust。</li></ul>',5))])}const _=i(p,[["render",c]]);export{C as __pageData,_ as default};
